def validate_BlendAuthoringEdit(value: BlendAuthoringEdit) -> None:
    if isinstance(value, BlendAuthoringEditCreateTable):
        validate_BlendShapeKeyTable(value.table)
    elif isinstance(value, BlendAuthoringEditCreateConstraint):
        validate_BlendShapeConstraint(value.constraint)
    elif isinstance(value, BlendAuthoringEditCreateBinding):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.target_id, str):
            raise ValueError("Expected string")
        validate_BlendShapeTargetKind(value.target_kind)
        if not isinstance(value.key_table_id, str):
            raise ValueError("Expected string")
    elif isinstance(value, BlendAuthoringEditTable):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        validate_BlendTableOperation(value.operation)
    elif isinstance(value, BlendAuthoringEditConstraint):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.parameter_id, str):
            raise ValueError("Expected string")
        if not isinstance(value.samples, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.samples:
            validate_ConstraintSample(v0)
    elif isinstance(value, BlendAuthoringEditSetBindingTable):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.key_table_id, str):
            raise ValueError("Expected string")
        if type(value.reset) is not bool:
            raise ValueError("Expected bool")
    else:
        raise TypeError("Expected BlendAuthoringEdit")

def encode_BlendAuthoringEdit(value: BlendAuthoringEdit) -> object:
    if isinstance(value, BlendAuthoringEditCreateTable):
        return {'CreateTable': {'table': encode_BlendShapeKeyTable(value.table)}}
    elif isinstance(value, BlendAuthoringEditCreateConstraint):
        return {'CreateConstraint': {'constraint': encode_BlendShapeConstraint(value.constraint)}}
    elif isinstance(value, BlendAuthoringEditCreateBinding):
        return {'CreateBinding': {'id': value.id, 'target_id': value.target_id, 'target_kind': encode_BlendShapeTargetKind(value.target_kind), 'key_table_id': value.key_table_id}}
    elif isinstance(value, BlendAuthoringEditTable):
        return {'Table': {'id': value.id, 'operation': encode_BlendTableOperation(value.operation)}}
    elif isinstance(value, BlendAuthoringEditConstraint):
        return {'Constraint': {'id': value.id, 'parameter_id': value.parameter_id, 'samples': [encode_ConstraintSample(v0) for v0 in value.samples]}}
    elif isinstance(value, BlendAuthoringEditSetBindingTable):
        return {'SetBindingTable': {'id': value.id, 'key_table_id': value.key_table_id, 'reset': value.reset}}
    raise TypeError("Expected BlendAuthoringEdit")

